-- ===================================================
-- Supabase Schema & Seed for Historical Map Archive
-- ===================================================

-- 1. Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. Collections Table
CREATE TABLE IF NOT EXISTS collections (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name TEXT NOT NULL UNIQUE,
    slug TEXT NOT NULL UNIQUE,
    category TEXT NOT NULL,
    item_count INT DEFAULT 0,
    total_size BIGINT DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 3. Items Table
CREATE TABLE IF NOT EXISTS items (
    id TEXT PRIMARY KEY,
    filename TEXT NOT NULL,
    relative_path TEXT NOT NULL,
    collection_name TEXT NOT NULL,
    subcollection TEXT,
    category TEXT NOT NULL,
    title TEXT,
    author TEXT,
    publication TEXT,
    date_depicted TEXT,
    page_number TEXT,
    citation TEXT,
    format TEXT NOT NULL,
    file_size BIGINT NOT NULL,
    thumbnail_url TEXT,
    preview_url TEXT,
    storage_thumbnail_path TEXT,
    storage_preview_path TEXT,
    search_vector TSVECTOR GENERATED ALWAYS AS (
        to_tsvector('english', coalesce(title, '') || ' ' || coalesce(citation, '') || ' ' || coalesce(author, '') || ' ' || coalesce(publication, '') || ' ' || coalesce(collection_name, '') || ' ' || coalesce(date_depicted, ''))
    ) STORED,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 4. Full Text Search & Indexes
CREATE INDEX IF NOT EXISTS items_search_idx ON items USING GIN(search_vector);
CREATE INDEX IF NOT EXISTS items_collection_idx ON items(collection_name);
CREATE INDEX IF NOT EXISTS items_category_idx ON items(category);
CREATE INDEX IF NOT EXISTS items_year_idx ON items(date_depicted);

-- 5. Row Level Security (Public Read Access)
ALTER TABLE collections ENABLE ROW LEVEL SECURITY;
ALTER TABLE items ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public read-only access on collections" ON collections FOR SELECT USING (true);
CREATE POLICY "Allow public read-only access on items" ON items FOR SELECT USING (true);

